          const stallPromise = new Promise<never>((_, reject) => {
            stallTimer = setTimeout(() => {
              const err = new ReviewerRunError("timeout", "Reviewer stalled: no stream events for 180s");
              controller.abort(err);
              reject(err);
            }, REVIEW_STALL_MS);
            stallTimer.unref?.();
